(()=>{
'use strict';
const paths = {
 car:'M3 15v4m18-4v4M3 15l1-5 3-5h10l3 5 1 5v2H3zM4 10h16M7 14h2m6 0h2M7 5l-2 5m12-5 2 5',
 search:'M21 21l-5-5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',
 bell:'M6 8a6 6 0 0 1 12 0v6l3 3H3l3-3zM10 21h4',
 down:'M6 9l6 6 6-6',right:'M9 5l7 7-7 7',arrow:'M4 12h16m-7-7 7 7-7 7',
 calendar:'M5 5h14v16H5zM8 2v6m8-6v6M5 10h14',
 history:'M3 11a9 9 0 1 1 2 7M3 4v7h7m2-5v6l4 2',
 parts:'M4 4h6v6H4zM14 4h6v6h-6zM4 14h6v6H4zM14 14h6v6h-6z',
 chat:'M21 11a9 9 0 0 1-9 9H5l-4 3 2-7a9 9 0 1 1 18-5zM8 10h.01M12 10h.01M16 10h.01',
 scan:'M3 8V3h5m8 0h5v5m0 8v5h-5M8 21H3v-5M7 12h10',
 check:'M5 12l4 4L20 5',
 shield:'M12 2l9 4v6c0 5-9 10-9 10S3 17 3 12V6zM8 12l3 3 5-6',
 wheel:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0M4 8l8 4 8-4M12 12v9M8 3l4 9 4-9',
 engine:'M5 8h13v10H5zM8 5h7M11 5v3M2 11v5m19-6v7M5 12H2m16 1h3',
 mileage:'M3 17a9 9 0 1 1 18 0M12 14l5-5M5 17h14',
 book:'M12 5C9 2 4 3 2 4v16c4-2 7-1 10 1 3-2 6-3 10-1V4c-4-2-7-1-10 1zM12 5v16',
 wrench:'M21 3l-5 5-3-3 5-5a7 7 0 0 0-8 9L2 18a3 3 0 0 0 4 4l9-9a7 7 0 0 0 6-10z',
 chart:'M4 21V12h3v9M11 21V7h3v14M18 21V2h3v19',
 edit:'M3 17l12-12 4 4L7 21H3zM15 5l3-3 4 4-3 3',
 database:'M21 6c0 5-18 5-18 0s18-5 18 0zM3 6v12c0 5 18 5 18 0V6M3 12c0 5 18 5 18 0',
 bolt:'M13 2L4 14h7l-1 8 10-13h-8z',
 stack:'M12 2l10 5-10 5L2 7zM2 12l10 5 10-5M2 17l10 5 10-5'
};
function icon(name){return `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.car}"/></svg>`}
const STORE='autoguide-servicebook-v1';
const TYPES={oil:'Масло и фильтр',filters:'Фильтры',brakes:'Тормоза',tires:'Шины и диски',diagnostic:'Диагностика',other:'Прочие работы'};
const money=n=>Number(n).toLocaleString('ru-RU',{maximumFractionDigits:2})+' ₽';
const km=n=>Number(n).toLocaleString('ru-RU')+' км';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const date=s=>new Date(s+'T12:00:00').toLocaleDateString('ru-RU');
const today=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
const uid=()=>globalThis.crypto?.randomUUID?.()||Date.now().toString(36)+Math.random().toString(36).slice(2);
const sample={version:1,vehicle:{mileage:84500,vin:'',oilInterval:15000},records:[
{id:'demo-1',date:'2021-03-12',mileage:10000,type:'oil',title:'Замена масла и масляного фильтра',amount:6500,service:'Автоцентр Север',note:'Масло по допуску производителя'},
{id:'demo-2',date:'2022-08-18',mileage:30000,type:'filters',title:'Плановое ТО, воздушный и салонный фильтры',amount:12800,service:'Автоцентр Север',note:''},
{id:'demo-3',date:'2024-05-14',mileage:60000,type:'diagnostic',title:'Свечи зажигания и диагностика',amount:17400,service:'VAG Service',note:''},
{id:'demo-4',date:'2026-04-18',mileage:71000,type:'oil',title:'Замена масла и масляного фильтра',amount:8400,service:'VAG Service',note:'Сохранён заказ-наряд'},
{id:'demo-5',date:'2026-09-12',mileage:82000,type:'brakes',title:'Замена передних тормозных колодок',amount:11500,service:'Точка сервиса',note:''},
{id:'demo-6',date:'2026-10-05',mileage:83800,type:'diagnostic',title:'Компьютерная диагностика',amount:4000,service:'VAG Service',note:'Ошибок не обнаружено'}],documents:[{id:'insurance',title:'Полис ОСАГО',number:'•••• 5841',expires:'2026-12-12'},{id:'license',title:'Водительское удостоверение',number:'•••• 2098',expires:'2030-06-18'},{id:'inspection',title:'Диагностическая карта',number:'Дата для напоминания',expires:'2027-04-15'}],tuning:[]};
function validDate(s){return typeof s==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(s)&&Number.isFinite(Date.parse(s+'T12:00:00Z'))&&new Date(s+'T12:00:00Z').toISOString().slice(0,10)===s}
function normalize(r){if(!r||typeof r!=='object')throw Error('Запись должна быть объектом.');const out={id:uid(),date:String(r.date||'').trim(),mileage:Number(r.mileage),amount:Number(String(r.amount??'').replace(',','.')),type:String(r.type||'other'),title:String(r.title||'').trim(),service:String(r.service||'').trim(),note:String(r.note||'').trim()};if(!validDate(out.date))throw Error('Некорректная дата: ожидается ГГГГ-ММ-ДД.');if(!['number','string'].includes(typeof r.mileage)||String(r.mileage).trim()===''||!Number.isSafeInteger(out.mileage)||out.mileage<0||out.mileage>3000000)throw Error('Пробег должен быть целым числом от 0 до 3 000 000.');if(!['number','string'].includes(typeof r.amount)||String(r.amount).trim()===''||!Number.isFinite(out.amount)||out.amount<0||out.amount>100000000||Math.abs(out.amount*100-Math.round(out.amount*100))>0.0001)throw Error('Стоимость должна быть неотрицательной, с точностью до копеек.');if(!out.title||out.title.length>180)throw Error('Название работы: от 1 до 180 символов.');if(out.service.length>120||out.note.length>2000)throw Error('Слишком длинное название сервиса или примечание.');if(!TYPES[out.type])throw Error('Неизвестная категория работы.');return out}
let storageError='';
function readState(){try{const raw=localStorage.getItem(STORE);if(!raw)return structuredClone(sample);const s=JSON.parse(raw);if(s.version!==1||!Array.isArray(s.records)||s.records.length>2000||!Array.isArray(s.documents)||!Array.isArray(s.tuning)||!Number.isSafeInteger(s.vehicle?.mileage)||s.vehicle.mileage<0||!Number.isSafeInteger(s.vehicle.oilInterval)||s.vehicle.oilInterval<1000||s.vehicle.oilInterval>50000)throw Error('Неверный формат сохранения');s.records=s.records.map(r=>({...normalize(r),id:typeof r.id==='string'?r.id:uid()}));s.documents=s.documents.map(d=>{if(!validDate(d.expires))throw Error('Неверная дата документа');return{id:String(d.id),title:String(d.title),number:String(d.number||''),expires:d.expires}});return s}catch(e){storageError='Сохранение браузера недоступно или повреждено. Показаны примеры; сначала экспортируйте нужные данные.';return structuredClone(sample)}}
let state=readState(),section='home',pendingImport=[],historySearch='',historyType='all',historyYear='all',tuningFilter='all',toastTimer;
function persist(){try{localStorage.setItem(STORE,JSON.stringify(state));storageError='';return true}catch(e){storageError='Изменения пока доступны только в открытой вкладке: сохранение браузера не сработало. Экспортируйте историю в JSON.';toast(storageError);return false}}
function toast(message){const el=document.getElementById('toast');el.textContent=message;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),4500)}
const sorted=()=>[...state.records].sort((a,b)=>b.date.localeCompare(a.date)||b.mileage-a.mileage);
function oilDue(){const oils=sorted().filter(r=>r.type==='oil');const base=oils.length?oils[0].mileage:0;return base+state.vehicle.oilInterval}
function dueText(target){const d=target-state.vehicle.mileage;return d>0?'Через '+km(d):d===0?'Пора выполнить ТО':'Просрочено на '+km(-d)}
const spent=()=>state.records.reduce((n,r)=>n+r.amount,0);
const nav=[['home','car','Мой автомобиль'],['history','history','История'],['maintenance','calendar','План ТО'],['expenses','chart','Расходы'],['tuning','wrench','Тюнинг'],['documents','book','Документы']];
function action(label,doAction,style='secondary',i=''){return `<button class="${style}" data-action="${doAction}">${i?icon(i):''}${label}</button>`}
function heading(title,subtitle,buttons=''){return `<div class="page-heading"><div><h1>${title}</h1><p>${subtitle}</p></div><div class="heading-actions">${buttons}</div></div>`}
function stats(){const month=today().slice(0,7);const sum=state.records.filter(r=>r.date.startsWith(month)).reduce((n,r)=>n+r.amount,0);return `<div class="stats">${[['mileage','Текущий пробег',km(state.vehicle.mileage),'Обновите после поездки'],['wrench','До замены масла',oilDue()>state.vehicle.mileage?km(oilDue()-state.vehicle.mileage):'Пора на ТО','Регламент можно настроить'],['chart','Расходы за месяц',money(sum),'По записям в журнале'],['history','Работ в истории',state.records.length,'Сервисы, детали и затраты']].map(([i,l,v,s])=>`<div class="stat"><div class="stat-top">${l}${icon(i)}</div><strong>${v}</strong><small>${s}</small></div>`).join('')}</div>`}
function sidebar(){return `<aside class="sidebar"><section class="car-card"><div class="car-visual"><h2>Škoda Octavia</h2><p>2020 · 1.4 TSI · DSG</p><img src="assets/car.png" alt="Серебристая Škoda Octavia"></div><div class="car-info"><span class="tag">Мой автомобиль · пример</span><div class="spec"><span>Двигатель</span><b>1.4 TSI / бензин</b></div><div class="spec"><span>Пробег</span><b>${km(state.vehicle.mileage)}</b></div><div class="spec"><span>VIN</span><b>${esc(state.vehicle.vin?state.vehicle.vin.slice(0,3)+'••••'+state.vehicle.vin.slice(-4):'Не указан')}</b></div>${action('Редактировать авто','vehicle','primary wide','edit')}</div></section><section class="aside-card"><h3 class="aside-title">${icon('shield')}На контроле</h3><div class="health"><strong>Обслуживание</strong><span class="status-pill ${oilDue()-state.vehicle.mileage<2000?'warn':''}">${oilDue()>state.vehicle.mileage?'Скоро ТО':'Пора на ТО'}</span></div><p>Интервалы задаются вручную. Сверяйте план с регламентом вашего автомобиля.</p><button class="aside-link" data-nav="maintenance">Открыть план ТО ${icon('right')}</button></section><section class="aside-card"><h3 class="aside-title">${icon('database')}Ваша сервисная книжка</h3><p>Записи хранятся в этом браузере. Скачивайте резервную копию для переноса на другое устройство.</p><button class="aside-link" data-action="export-json">Экспорт истории ${icon('arrow')}</button></section></aside>`}
function timeline(){const recent=sorted().slice(0,4).reverse();return `<div class="timeline">${recent.map(r=>`<div class="event"><span class="event-dot">${icon('check')}</span><h3>${km(r.mileage)}<time>${date(r.date)}</time></h3><p>${esc(r.title)}</p><div class="tiny-price">${money(r.amount)} · ${esc(r.service||'Сервис не указан')}</div></div>`).join('')}<div class="event now"><span class="event-dot">${icon('check')}</span><h3>${km(state.vehicle.mileage)}<time>Сейчас</time></h3><p>Текущее состояние автомобиля</p></div><div class="event future"><span class="event-dot">${icon('wrench')}</span><h3>${km(oilDue())}<time>${dueText(oilDue())}</time></h3><p>Следующее ТО — масло и масляный фильтр</p></div></div>`}
function home(){return heading('Сервисная книжка','История, планы и забота о вашем автомобиле — в одном месте',action('Загрузить историю','import','secondary','database')+action('Добавить работу','add','primary','wrench'))+stats()+`<div class="home-grid"><section class="card"><div class="card-heading"><h2>История обслуживания</h2><button class="text-btn" data-nav="history">Все записи ${icon('right')}</button></div>${timeline()}</section><div class="right-stack"><section class="service-banner"><img src="assets/car.png" alt=""><div class="banner-label"><span class="banner-icon">${icon('wrench')}</span><div><small>Ближайшее ТО</small><strong>Замена масла<br>${dueText(oilDue()).toLowerCase()}</strong></div></div></section><div class="mini-grid"><section class="card mini-card"><h3>Расходы за всё время</h3><div class="expense-amount">${money(spent())}</div><div class="subtext">Работы и запчасти в журнале</div><div class="chart" role="img" aria-label="Сравнение стоимости последних работ">${sorted().slice(0,8).reverse().map(r=>`<i style="--h:${Math.max(10,Math.round(r.amount/Math.max(1,...state.records.map(x=>x.amount))*100))}%"></i>`).join('')}</div><button class="aside-link" data-nav="expenses">Разобрать расходы ${icon('right')}</button></section><section class="card mini-card"><h3>Документы и сроки</h3>${state.documents.slice(0,2).map(d=>`<div class="doc-mini">${icon('shield')}<div><b>${esc(d.title)}</b><small>До ${date(d.expires)}</small></div></div>`).join('')}<button class="aside-link" data-nav="documents">Все документы ${icon('right')}</button></section></div></div></div><div class="lower-grid"><section class="card tuning-preview"><div class="card-heading"><h2>Что можно улучшить?</h2><button class="text-btn" data-nav="tuning">Идеи тюнинга ${icon('right')}</button></div><div class="subtext">Больше комфорта, удобства и удовольствия от поездок.</div><div class="tuning-tags"><span>Шумоизоляция</span><span>CarPlay / Android Auto</span><span>Видеорегистратор</span></div><div class="subtext">${state.tuning.length} идей в вашем списке. Совместимость уточняется отдельно.</div></section><section class="card assistant-card"><div class="assistant-head"><span class="banner-icon">${icon('chat')}</span><div><h3>Спросите об автомобиле</h3><p>Подсказки по эксплуатации и обслуживанию</p></div></div><form class="chat-input" id="quick-chat"><input name="question" placeholder="Например: что проверить перед поездкой?" aria-label="Вопрос помощнику" required><button class="primary" aria-label="Отправить вопрос">${icon('arrow')}</button></form></section></div>`}
function recordsTable(records,preview=false){if(!records.length)return '<div class="empty">Записей пока нет. Добавьте работу или загрузите историю.</div>';return `<table class="table"><thead><tr><th>Дата / пробег</th><th>Работа</th><th>Сервис</th><th>Стоимость</th>${preview?'':'<th>Действия</th>'}</tr></thead><tbody>${records.map(r=>`<tr><td>${date(r.date)}<br><small>${km(r.mileage)}</small></td><td><strong>${esc(r.title)}</strong><small>${TYPES[r.type]}</small></td><td>${esc(r.service||'—')}</td><td>${money(r.amount)}</td>${preview?'':`<td><div class="table-actions"><button data-edit="${esc(r.id)}" aria-label="Редактировать работу">${icon('edit')}</button><button class="delete" data-delete="${esc(r.id)}" aria-label="Удалить работу">×</button></div></td>`}</tr>`).join('')}</tbody></table>`}
function filteredHistory(){return sorted().filter(r=>(historyType==='all'||r.type===historyType)&&(historyYear==='all'||r.date.startsWith(historyYear))&&[r.title,r.service,r.note].some(t=>t.toLowerCase().includes(historySearch.toLowerCase())))}
function history(){const years=[...new Set(state.records.map(r=>r.date.slice(0,4)))].sort().reverse();return heading('История обслуживания','Все работы, запчасти и расходы — без потерянных заметок',action('Импорт CSV / JSON','import','secondary','database')+action('Добавить работу','add','primary','wrench'))+`<div class="tools"><input id="history-search" type="search" placeholder="Найти работу или сервис" value="${esc(historySearch)}" aria-label="Поиск в истории"><select id="history-type" aria-label="Категория"><option value="all">Все категории</option>${Object.entries(TYPES).map(([v,t])=>`<option value="${v}" ${historyType===v?'selected':''}>${t}</option>`).join('')}</select><select id="history-year" aria-label="Год"><option value="all">Все годы</option>${years.map(y=>`<option ${historyYear===y?'selected':''}>${y}</option>`).join('')}</select></div><div class="table-wrap" id="records-table">${recordsTable(filteredHistory())}</div><div class="export-row">${action('Экспорт JSON','export-json')}${action('Экспорт CSV','export-csv')}<small id="history-count">Показано записей: ${filteredHistory().length} из ${state.records.length}</small></div>`}
const jobs=()=>[{title:'Масло и масляный фильтр',target:oilDue(),type:'oil',price:8400,icon:'wrench',text:'Интервал '+km(state.vehicle.oilInterval)+'. Можно настроить по регламенту.'},{title:'Воздушный и салонный фильтры',target:90000,type:'filters',price:4500,icon:'parts',text:'Пример планового пробега. Состояние зависит от условий эксплуатации.'},{title:'Проверка тормозов',target:90000,type:'brakes',price:2500,icon:'wheel',text:'Проверка износа колодок, дисков и состояния тормозной жидкости.'},{title:'Шины и давление',target:null,type:'tires',price:3000,icon:'wheel',text:'Сезонная проверка состояния, давления и равномерности износа.'},{title:'Аккумулятор',target:null,type:'diagnostic',price:1500,icon:'bolt',text:'Диагностика перед холодным сезоном или при затруднённом запуске.'},{title:'Диагностика электроники',target:null,type:'diagnostic',price:4000,icon:'engine',text:'При ошибках на панели или изменениях в поведении автомобиля.'}];
function maintenance(){return heading('План технического обслуживания','Следите за пробегом и отмечайте выполненные работы',action('Настроить интервал','interval','secondary','calendar'))+`<div class="callout">${icon('book')}План демонстрационный. Интервалы и перечень работ уточняйте по руководству конкретного автомобиля.</div><div class="maintenance-grid">${jobs().map((j,i)=>`<article class="feature-card"><div class="service-top"><span class="feature-icon">${icon(j.icon)}</span><span class="status-pill ${j.target&&j.target-state.vehicle.mileage<2000?'warn':''}">${j.target?'По пробегу':'По необходимости'}</span></div><h3>${j.title}</h3><p>${j.text}</p><div class="service-due">${j.target?dueText(j.target):'Проверьте по сезону'}<small>${j.target?'Плановый пробег: '+km(j.target):'Точная дата не назначена'}</small></div><button class="primary" data-job="${i}">Отметить выполненной</button></article>`).join('')}</div>`}
const tuningItems=[{id:'sound',cat:'comfort',label:'Комфорт',title:'Шумоизоляция дверей',min:18000,max:35000,icon:'shield',text:'Меньше дорожного шума и более приятное звучание штатной акустики.',compat:'Проверить конструкцию дверей и влагозащиту.'},{id:'carplay',cat:'media',label:'Мультимедиа',title:'CarPlay / Android Auto',min:12000,max:45000,icon:'chat',text:'Карты, музыка и звонки на экране мультимедийной системы.',compat:'Зависит от модели головного устройства и лицензий.'},{id:'camera',cat:'safety',label:'Удобство',title:'Камера заднего вида',min:10000,max:22000,icon:'car',text:'Больше уверенности при парковке и манёврах во дворе.',compat:'Уточнить поддержку блока мультимедиа и проводку.'},{id:'recorder',cat:'safety',label:'Безопасность',title:'Видеорегистратор',min:6000,max:18000,icon:'shield',text:'Запись дорожных событий с аккуратным скрытым подключением.',compat:'Нужна защита аккумулятора при парковочной записи.'},{id:'tires',cat:'chassis',label:'Колёса',title:'Комфортные шины',min:28000,max:60000,icon:'wheel',text:'Подбор шин под дороги, сезон и привычный стиль поездок.',compat:'Размер, индекс нагрузки и скорости — по допускам авто.'},{id:'engine',cat:'engine',label:'Двигатель',title:'Консультация по настройке ЭБУ',min:3000,max:8000,icon:'engine',text:'Диагностика и оценка возможностей до любых изменений прошивки.',compat:'Не обещает прирост мощности. Уточнить ресурс, гарантию и требования регистрации.'}];
function tuning(){const selected=tuningItems.filter(t=>state.tuning.includes(t.id));const items=tuningItems.filter(t=>tuningFilter==='all'||t.cat===tuningFilter);return heading('Идеи для вашего автомобиля','Соберите список улучшений — от комфорта до мультимедиа')+`<div class="budget"><div><span>Ориентировочный бюджет выбранных идей · ${selected.length}</span><strong>${money(selected.reduce((n,t)=>n+t.min,0))} — ${money(selected.reduce((n,t)=>n+t.max,0))}</strong></div><p>Примерные диапазоны для макета, а не предложения сервисов. Совместимость и итоговую стоимость нужно подтвердить у специалиста.</p></div><div class="tools"><select id="tuning-filter" aria-label="Категория улучшений">${[['all','Все улучшения'],['comfort','Комфорт'],['media','Мультимедиа'],['safety','Удобство и безопасность'],['chassis','Колёса'],['engine','Двигатель']].map(([v,t])=>`<option value="${v}" ${tuningFilter===v?'selected':''}>${t}</option>`).join('')}</select><span class="subtext">В списке: ${selected.map(t=>esc(t.title)).join(', ')||'пока ничего'}</span></div><div class="tuning-grid">${items.map(t=>`<article class="feature-card ${state.tuning.includes(t.id)?'selected':''}"><span class="label">${t.label}</span><div class="feature-icon">${icon(t.icon)}</div><h3>${t.title}</h3><p>${t.text}</p><div class="price">${money(t.min)} — ${money(t.max)}</div><div class="meta">${t.compat}</div><button class="${state.tuning.includes(t.id)?'primary':'secondary'}" data-tuning="${t.id}">${state.tuning.includes(t.id)?'✓ В списке · убрать':'Добавить в список'}</button></article>`).join('')}</div>`}
function daysTo(s){return Math.ceil((new Date(s+'T00:00:00')-new Date(today()+'T00:00:00'))/86400000)}
function documents(){return heading('Документы и напоминания','Важные даты, чтобы не вспоминать о них в последний момент')+`<div class="callout">${icon('calendar')}Напоминания показываются внутри приложения. Push, email и проверка документов по реестрам не подключены. Копии документов не загружаются.</div><div class="documents-grid">${state.documents.map(d=>{const days=daysTo(d.expires);return `<article class="feature-card"><div class="feature-icon">${icon('shield')}</div><h3>${esc(d.title)}</h3><p>${esc(d.number)}</p><div class="doc-date">${date(d.expires)}</div><div class="doc-note">${days<0?'Срок истёк '+(-days)+' дн. назад':days===0?'Истекает сегодня':'До окончания: '+days+' дн.'}</div><button class="secondary" data-document="${esc(d.id)}">Изменить дату</button></article>`}).join('')}</div>`}
function expenses(){const groups=Object.entries(TYPES).map(([k,t])=>({title:t,amount:state.records.filter(r=>r.type===k).reduce((n,r)=>n+r.amount,0)})).filter(g=>g.amount).sort((a,b)=>b.amount-a.amount);return heading('Расходы на автомобиль','Работы и запчасти на основании вашей истории',action('Добавить расход','add','primary','chart'))+stats()+`<section class="card"><div class="card-heading"><h2>За всё время: ${money(spent())}</h2><span class="subtext">Топливо и страховка в эту сумму не включены</span></div><div class="expense-list">${groups.map(g=>`<div class="expense-bar"><span>${g.title}</span><div><i style="--w:${Math.round(g.amount/Math.max(1,...groups.map(x=>x.amount))*100)}%"></i></div><b>${money(g.amount)}</b></div>`).join('')||'<p class="subtext">Добавьте первую работу с расходом.</p>'}</div></section><div class="export-row">${action('Скачать CSV','export-csv')}${action('Скачать JSON','export-json')}</div>`}
function render(){const templates={home,history,maintenance,expenses,tuning,documents};document.getElementById('root').innerHTML=`<header class="topbar"><a class="logo" href="index.html">${icon('car')}АвтоГид AI</a><nav class="topnav" aria-label="Основная навигация">${nav.map(([v,i,t])=>`<button class="${section===v?'active':''}" data-nav="${v}">${icon(i)}${t}</button>`).join('')}</nav><div class="account"><button class="icon-btn" data-action="search" aria-label="Поиск">${icon('search')}</button><button class="icon-btn" data-action="notifications" aria-label="Напоминания">${icon('bell')}</button><span class="avatar">А</span></div></header><div class="shell"><div class="breadcrumb"><span>Главная / Мой автомобиль / ${nav.find(n=>n[0]===section)?.[2]||''}</span><span>Škoda Octavia · Ваша сервисная книжка</span></div>${storageError?`<div class="callout">${esc(storageError)}</div>`:''}<div class="layout">${sidebar()}<main class="workspace" id="workspace">${templates[section]()}</main></div><footer class="footer"><span>© 2026 АвтоГид AI · Прототип: данные авто демонстрационные, VIN-декодер и LLM API не подключены.<br>Ваши изменения сохраняются только в этом браузере. Для переноса истории используйте экспорт.</span><span>Сделано для спокойных поездок</span></footer></div>`;bindView()}
function navigate(s){if(!nav.some(n=>n[0]===s))return;section=s;window.history.replaceState(null,'','#'+s);render();window.scrollTo({top:0,behavior:'instant'})}
const modal=document.getElementById('modal');
function openModal(title,body){if(modal.open)modal.close();modal.innerHTML=`<div class="modal-head"><h2 id="modal-title">${esc(title)}</h2><button type="button" id="close-modal" aria-label="Закрыть">×</button></div>${body}`;modal.showModal();document.getElementById('close-modal').onclick=()=>modal.close();modal.querySelector('[data-cancel]')?.addEventListener('click',()=>modal.close())}
modal.addEventListener('click',e=>{if(e.target!==modal)return;const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)modal.close()});
function buttons(save='Сохранить'){return `<div class="form-error" id="form-error" role="alert"></div><div class="modal-actions"><button class="secondary" type="button" data-cancel>Отмена</button><button class="primary" type="submit">${save}</button></div>`}
function field(label,name,value='',type='text',attrs=''){return `<div class="form-field"><label for="f-${name}">${label}</label><input id="f-${name}" name="${name}" type="${type}" value="${esc(value)}" ${attrs}></div>`}
function recordForm(id,job){const r=id?state.records.find(r=>r.id===id):{date:today(),mileage:state.vehicle.mileage,type:job?.type||'other',title:job?.title||'',amount:job?.price||'',service:'',note:''};if(!r)return;openModal(id?'Редактировать работу':'Добавить работу',`<form id="record-form"><div class="form-grid">${field('Дата выполнения','date',r.date,'date','required')}${field('Пробег, км','mileage',r.mileage,'number','required min="0" max="3000000" step="1"')}<div class="form-field full"><label for="f-title">Название работы</label><input id="f-title" name="title" value="${esc(r.title)}" maxlength="180" placeholder="Например: замена масла и фильтра" required></div><div class="form-field"><label for="f-type">Категория</label><select id="f-type" name="type">${Object.entries(TYPES).map(([v,t])=>`<option value="${v}" ${r.type===v?'selected':''}>${t}</option>`).join('')}</select></div>${field('Стоимость, ₽','amount',r.amount,'number','required min="0" max="100000000" step="0.01"')}<div class="form-field full"><label for="f-service">Сервис / выполнено самостоятельно</label><input id="f-service" name="service" value="${esc(r.service)}" maxlength="120" placeholder="Название сервиса"></div><div class="form-field full"><label for="f-note">Примечание</label><textarea id="f-note" name="note" maxlength="2000">${esc(r.note)}</textarea></div></div>${buttons(id?'Сохранить изменения':'Добавить в историю')}</form>`);document.getElementById('record-form').onsubmit=e=>{e.preventDefault();try{const data=normalize(Object.fromEntries(new FormData(e.target)));if(id){data.id=id;state.records=state.records.map(r=>r.id===id?data:r)}else{if(state.records.length>=2000)throw Error('В истории уже 2000 записей. Сначала экспортируйте архив.');state.records.push(data)}state.vehicle.mileage=Math.max(state.vehicle.mileage,data.mileage);persist();modal.close();render();toast(id?'Работа обновлена.':'Работа добавлена в историю.')}catch(err){document.getElementById('form-error').textContent=err.message}}}
function vehicleForm(){openModal('Карточка автомобиля',`<form id="vehicle-form"><p class="modal-hint">Škoda Octavia 2020 · 1.4 TSI — демонстрационная модель. VIN сохраняется как заметка и не декодируется.</p><div class="form-grid">${field('Текущий пробег, км','mileage',state.vehicle.mileage,'number','required min="0" max="3000000" step="1"')}<div class="form-field"><label for="f-vin">VIN автомобиля (необязательно)</label><input id="f-vin" name="vin" value="${esc(state.vehicle.vin)}" maxlength="17" placeholder="17 символов VIN" autocomplete="off"></div></div>${buttons()}</form>`);document.getElementById('vehicle-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),m=Number(f.get('mileage')),v=String(f.get('vin')).trim().toUpperCase();if(!Number.isSafeInteger(m)||m<0||m>3000000||v&&!/^[A-HJ-NPR-Z0-9]{17}$/.test(v)){document.getElementById('form-error').textContent='Проверьте пробег и VIN (17 символов без I, O и Q).';return}state.vehicle.mileage=m;state.vehicle.vin=v;persist();modal.close();render();toast('Карточка автомобиля обновлена.')};}
function intervalForm(){openModal('Интервал замены масла',`<form id="interval-form"><p class="modal-hint">Укажите интервал из регламента вашего автомобиля. План рассчитывается от пробега последней замены масла в истории.</p><div class="form-grid">${field('Интервал, км','interval',state.vehicle.oilInterval,'number','required min="1000" max="50000" step="1"')}</div>${buttons()}</form>`);document.getElementById('interval-form').onsubmit=e=>{e.preventDefault();const n=Number(new FormData(e.target).get('interval'));if(!Number.isSafeInteger(n)||n<1000||n>50000){document.getElementById('form-error').textContent='Допустим интервал от 1 000 до 50 000 км.';return}state.vehicle.oilInterval=n;persist();modal.close();render();toast('Интервал обновлён.')};}
function download(name,text,type){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([text],{type}));a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function csvCell(v){let text=String(v??'');if(/^[=+\-@\t\r]/.test(text))text="'"+text;return '"'+text.replace(/"/g,'""')+'"'}
function exportData(format){if(format==='json')download('autoguide-history.json',JSON.stringify({format:'autoguide-history',version:1,records:state.records.map(({id,...r})=>r)},null,2),'application/json');else{const fields=['date','mileage','type','title','amount','service','note'];download('autoguide-history.csv','\uFEFF'+[fields.join(';'),...state.records.map(r=>fields.map(k=>csvCell(r[k])).join(';'))].join('\r\n'),'text/csv;charset=utf-8')}}
function parseCSV(text){text=text.replace(/^\uFEFF/,'');const first=text.split(/\r?\n/)[0]||'';const delimiter=first.includes(';')?';':',';let rows=[],row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){cell+='"';i++}else quoted=!quoted}else if(c===delimiter&&!quoted){row.push(cell);cell=''}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(c=>c.trim()))rows.push(row);row=[];cell=''}else cell+=c}if(quoted)throw Error('В CSV не закрыты кавычки.');row.push(cell);if(row.some(c=>c.trim()))rows.push(row);if(!rows.length)throw Error('Файл пуст.');const headers=rows.shift().map(h=>h.trim().toLowerCase());if(new Set(headers).size!==headers.length)throw Error('В CSV повторяются названия колонок.');for(const k of ['date','mileage','title','amount'])if(!headers.includes(k))throw Error('В CSV отсутствует колонка '+k+'.');return rows.map((r,i)=>{if(r.length!==headers.length)throw Error('Строка '+(i+2)+': число значений не совпадает с колонками.');return Object.fromEntries(headers.map((h,j)=>[h,r[j]]))})}
function recordKey(r){return [r.date,r.mileage,r.type,r.title.trim().toLowerCase(),r.amount].join('|')}
let fileVersion=0;
function importForm(){pendingImport=[];openModal('Загрузить историю обслуживания',`<p class="modal-hint">Загрузите CSV или JSON из сервисной книжки. До подтверждения записи не добавляются. Файл обрабатывается в браузере и не отправляется на сервер.</p><div class="dropzone">${icon('database')}<p>Выберите файл · до 2 МБ и 2 000 записей</p><input id="import-file" type="file" accept=".csv,.json" aria-label="Файл истории обслуживания"></div><p class="modal-hint">Колонки CSV: date, mileage, type, title, amount, service, note.<br>Дата: ГГГГ-ММ-ДД. Типы: oil, filters, brakes, tires, diagnostic, other.</p><button class="text-btn" id="import-example">Скачать пример CSV</button><div class="form-error" id="import-error" role="alert"></div><p class="modal-hint" id="import-summary"></p><div class="preview-table" id="import-preview"></div><div class="modal-actions"><button class="secondary" data-cancel>Отмена</button><button class="primary" id="import-confirm" disabled>Добавить записи</button></div>`);document.getElementById('import-example').onclick=()=>download('history-example.csv','\uFEFFdate;mileage;type;title;amount;service;note\r\n2026-10-10;84000;tires;Сезонная смена шин;3500;Шиномонтаж;Проверено давление','text/csv;charset=utf-8');document.getElementById('import-file').onchange=async e=>{const version=++fileVersion,importInput=e.target;pendingImport=[];document.getElementById('import-confirm').disabled=true;document.getElementById('import-preview').innerHTML='';document.getElementById('import-error').textContent='';document.getElementById('import-summary').textContent='';const file=e.target.files[0];if(!file)return;try{if(file.size>2*1024*1024)throw Error('Размер файла превышает 2 МБ.');const text=await file.text();if(version!==fileVersion||!modal.open||!importInput.isConnected)return;let records;if(file.name.toLowerCase().endsWith('.json')){const value=JSON.parse(text);records=Array.isArray(value)?value:value?.records}else if(file.name.toLowerCase().endsWith('.csv'))records=parseCSV(text);else throw Error('Выберите файл CSV или JSON.');if(!Array.isArray(records)||records.length===0||records.length>2000)throw Error('Ожидается от 1 до 2000 записей.');const seen=new Set(state.records.map(recordKey));let duplicates=0;const prepared=[];records.forEach((r,i)=>{let entry;try{entry=normalize(r)}catch(err){throw Error('Запись '+(i+1)+': '+err.message)}const key=recordKey(entry);if(seen.has(key))duplicates++;else{seen.add(key);prepared.push(entry)}});if(state.records.length+prepared.length>2000)throw Error('После импорта будет больше 2000 записей.');pendingImport=prepared;document.getElementById('import-summary').textContent=`Готово к загрузке: ${prepared.length}. Пропущено совпадающих записей: ${duplicates}.`;document.getElementById('import-preview').innerHTML=recordsTable(prepared.slice(0,20),true);document.getElementById('import-confirm').disabled=!prepared.length}catch(err){if(version===fileVersion&&modal.open&&importInput.isConnected)document.getElementById('import-error').textContent=err.message}};document.getElementById('import-confirm').onclick=()=>{if(!pendingImport.length)return;const count=pendingImport.length;state.records.push(...pendingImport);state.vehicle.mileage=Math.max(state.vehicle.mileage,...pendingImport.map(r=>r.mileage));pendingImport=[];persist();modal.close();section='history';historySearch='';historyType='all';historyYear='all';render();toast('Добавлено записей: '+count+'.')};}
function deleteRecord(id){const r=state.records.find(r=>r.id===id);if(!r)return;openModal('Удалить запись?',`<p class="modal-hint">${esc(r.title)} · ${date(r.date)} · ${money(r.amount)}.<br>После удаления расходы и план ТО будут пересчитаны. Для резервной копии используйте экспорт.</p><div class="modal-actions"><button class="secondary" data-cancel>Отмена</button><button class="danger" id="confirm-delete">Удалить</button></div>`);document.getElementById('confirm-delete').onclick=()=>{state.records=state.records.filter(r=>r.id!==id);persist();modal.close();render();toast('Запись удалена.')};}
function documentForm(id){const doc=state.documents.find(d=>d.id===id);if(!doc)return;openModal(doc.title,`<form id="document-form"><p class="modal-hint">Сохраняется только дата для напоминания, без копии документа.</p><div class="form-grid">${field('Дата окончания','expires',doc.expires,'date','required')}</div>${buttons()}</form>`);document.getElementById('document-form').onsubmit=e=>{e.preventDefault();const value=String(new FormData(e.target).get('expires'));if(!validDate(value)){document.getElementById('form-error').textContent='Укажите корректную дату.';return}doc.expires=value;persist();modal.close();render();toast('Дата документа обновлена.')};}
function notifications(){const closeDocs=state.documents.filter(d=>daysTo(d.expires)<=60);openModal('На что обратить внимание',`<div class="ai-answer"><b>Замена масла</b><br>${dueText(oilDue())}. Плановый пробег: ${km(oilDue())}.${closeDocs.map(d=>`<br><br><b>${esc(d.title)}</b><br>Срок: ${date(d.expires)} (${daysTo(d.expires)<0?'истёк':'осталось '+daysTo(d.expires)+' дн.'}).`).join('')}</div><p class="modal-hint">Это напоминания внутри прототипа. Внешние уведомления не отправляются.</p>`)}
function assistant(question=''){openModal('Помощник автовладельца',`<p class="modal-hint">${question?'Ваш вопрос: '+esc(question):'Спросите об эксплуатации или откройте связанные разделы.'}</p><div class="ai-answer">Встроенная LLM ещё не подключена, поэтому здесь нет сгенерированного ответа.<br>Для подготовки к поездке можно свериться с руководством автомобиля и проверить сроки ТО в сервисной книжке.</div><div class="ai-chips"><button data-go="maintenance">План обслуживания</button><button data-go="documents">Сроки документов</button><button data-go="history">История работ</button></div>`);modal.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>{modal.close();navigate(b.dataset.go)})}
function search(){openModal('Найти в приложении','<div class="searchbox"><input id="search-input" type="search" placeholder="Раздел, работа или сервис" aria-label="Поисковый запрос"><div id="search-results"></div></div>');const input=document.getElementById('search-input');input.oninput=()=>{const query=input.value.trim().toLowerCase(),result=document.getElementById('search-results');result.replaceChildren();if(!query)return;const targets=nav.filter(n=>n[2].toLowerCase().includes(query)).map(n=>({name:n[2],go:n[0]}));sorted().filter(r=>[r.title,r.service].some(s=>s.toLowerCase().includes(query))).slice(0,8).forEach(r=>targets.push({name:r.title+' · '+date(r.date),go:'history',query:r.title}));targets.forEach(t=>{const b=document.createElement('button');b.className='search-result';b.textContent=t.name;b.onclick=()=>{if(t.query){historySearch=t.query;historyType='all';historyYear='all'}modal.close();navigate(t.go)};result.append(b)});if(!targets.length){const p=document.createElement('p');p.className='modal-hint';p.textContent='Ничего не найдено.';result.append(p)}};input.focus()}
function updateHistory(){document.getElementById('records-table').innerHTML=recordsTable(filteredHistory());document.getElementById('history-count').textContent=`Показано записей: ${filteredHistory().length} из ${state.records.length}`;bindRecordActions()}
function bindRecordActions(){document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>recordForm(b.dataset.edit));document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>deleteRecord(b.dataset.delete))}
function bindView(){document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>navigate(b.dataset.nav));const actions={add:()=>recordForm(),import:importForm,vehicle:vehicleForm,interval:intervalForm,'export-json':()=>exportData('json'),'export-csv':()=>exportData('csv'),search,notifications};document.querySelectorAll('[data-action]').forEach(b=>b.onclick=actions[b.dataset.action]);bindRecordActions();document.getElementById('history-search')?.addEventListener('input',e=>{historySearch=e.target.value;updateHistory()});document.getElementById('history-type')?.addEventListener('change',e=>{historyType=e.target.value;updateHistory()});document.getElementById('history-year')?.addEventListener('change',e=>{historyYear=e.target.value;updateHistory()});document.getElementById('tuning-filter')?.addEventListener('change',e=>{tuningFilter=e.target.value;render()});document.querySelectorAll('[data-tuning]').forEach(b=>b.onclick=()=>{const id=b.dataset.tuning;state.tuning=state.tuning.includes(id)?state.tuning.filter(x=>x!==id):[...state.tuning,id];persist();render()});document.querySelectorAll('[data-job]').forEach(b=>b.onclick=()=>recordForm(null,jobs()[Number(b.dataset.job)]));document.querySelectorAll('[data-document]').forEach(b=>b.onclick=()=>documentForm(b.dataset.document));document.getElementById('quick-chat')?.addEventListener('submit',e=>{e.preventDefault();assistant(String(new FormData(e.target).get('question')))});}
if(nav.some(n=>n[0]===location.hash.slice(1)))section=location.hash.slice(1);
window.addEventListener('hashchange',()=>{const target=location.hash.slice(1);if(nav.some(n=>n[0]===target)){section=target;render()}});
render();

})();
